/* ---------- the Hazards layer on these tours' stops shows volcanoes only (or the parts a stop names in haz:[…]);
   the per-stop on:[…] switching itself is shared (geoflock-mapsx.js) ---------- */
const mine=()=>typeof ps!=="undefined"&&ps&&IDS.includes(ps.tour);
let saved=null;
function hazInput(){return document.querySelector('.gf-ly-fold[data-ly="haz"] label.switch input')}
function hazParts(want){try{const L=window.GF_LAYERS;if(!L||!L.haz)return;
 if(want){if(!saved)saved=new Set(L.haz.parts);if([...L.haz.parts].sort().join()===want.slice().sort().join())return;L.haz.parts.clear();want.forEach(k=>L.haz.parts.add(k))}
 else{if(!saved)return;L.haz.parts.clear();saved.forEach(k=>L.haz.parts.add(k));saved=null}
 const i=hazInput();if(i&&i.checked)i.dispatchEvent(new Event("change",{bubbles:true}))}catch(e){console.error(e)}}
function stepHaz(){try{if(!mine())return;const St=psSteps()[ps.i];if(!St)return;hazParts((St.on||[]).includes("hazards")?(St.haz||["volc"]):null)}catch(e){console.error(e)}}
/* applied straight away and again a little later (a stop that changes the map mode restarts the tour) */
if(typeof psGo==="function"){const _g=psGo;psGo=function(i){stepHaz();const r=_g.apply(this,arguments);stepHaz();clearTimeout(psGo._p1h);psGo._p1h=setTimeout(stepHaz,1500);return r}}
if(typeof psEnd==="function"){const _e=psEnd;psEnd=function(){const was=mine();const r=_e.apply(this,arguments);if(was)setTimeout(()=>{if(!mine())hazParts(null)},700);return r}}

